    version: '0.1.36',
    sourceCommit: 'aaa',
    files: [
        { path: 'js/smAgent.js', sha256: 'hash-a', mode: '0644' },
        { path: 'js/common/smProvider.js', sha256: 'hash-b', mode: '0644' },
    ],
});

var SAME_PAYLOAD_MANIFEST = JSON.stringify({
    agent: 'sm_github',
    version: '0.1.37',
    sourceCommit: 'bbb',
    files: [
        { path: 'js/smAgent.js', sha256: 'hash-a', mode: '0644' },
