let SHIPPED_DIR = null;
let SHIPPED_CATALOG = null;
const SHIPPED_ZIP_MANIFESTS = {};

function shippedCatalog() {
  if (SHIPPED_CATALOG || !PREV_TAG || DRY_RUN) return SHIPPED_CATALOG;
