function resolveRequire(fromPath, spec) {
    var parts = fromPath.split('/');
    parts.pop(); // the requiring file's directory
    var segs = spec.split('/');
    for (var i = 0; i < segs.length; i++) {
        var seg = segs[i];
        if (seg === '' || seg === '.') continue;
        if (seg === '..') parts.pop();
        else parts.push(seg);
    }
    return parts.join('/');
}

