    SHIPPED_ZIP_MANIFESTS[key] = manifestJson;
  } catch (e) {
    console.warn(`::warning::could not fetch shipped ${key}.zip for the payload comparison (${String(e.message).split('\n')[0]}) — shipping at the candidate version`);
