366:/** Validates a zip against its embedded manifest (per-file sha256 inventory). */
367:function validatePack(zipPath) {
368:  // Read manifest.json from the zip without external tools (unzip -p).
369:  const manifestJson = execSync(`unzip -p ${JSON.stringify(zipPath)} manifest.json`, { encoding: 'utf8' });
