371:  const files = manifest.files || [];
372:  if (files.length === 0) throw new Error(`manifest.json in ${zipPath} has no files`);
373:  for (const f of files) {
374:    const bytes = execSync(`unzip -p ${JSON.stringify(zipPath)} ${JSON.stringify(f.path)}`);
375:    const actual = createHash('sha256').update(bytes).digest('hex');
376:    if (actual !== f.sha256) {
377:      throw new Error(`sha256 mismatch in ${zipPath}: ${f.path}`);
