36:    // Fresh stateful copy per call: a shared /g regex carries lastIndex
37:    // across calls (and resetting it mid-loop would rematch forever).
38:    var re = new RegExp(REQUIRE_RE.source, 'g');
39:    var m = re.exec(source);
40:    while (m !== null) {
41:        specs.push(m[2]);
42:        m = re.exec(source);
