    if (e.isDirectory()) walk(path.join(d, e.name), rp);
    else { paths.add(rp); if (rp.endsWith('.js')) sources.push({ path: rp, source: fs.readFileSync(path.join(d, e.name), 'utf8') }); }
  } };
  walk(dir, '');
  return { paths, sources, manifest: fs.readFileSync(path.join(dir, 'manifest.json'), 'utf8') };
}

