+/** Zip-layout path from [parts], '.'/'..'/empty segments normalized away. */
+function normalizePath(parts) {
+    var out = [];
+    for (var i = 0; i < parts.length; i++) {
+        var seg = parts[i];
+        if (seg === '' || seg === '.') continue;
+        if (seg === '..') out.pop();
+        else out.push(seg);
