```js
/**
 * Builds ONE agent pack zip at [version] with the full gh-812 integrity
 * chain: launch surface augment → payload-drift re-version (V3) → require
 * sanity gate → manifest validation. Returns { zipPath, version, files }.
 */
function buildPackRelease(agent, version, isAffected, shippedVersion) {
  let zip = buildPack(agent, version);
  augmentLaunchSurface(agent, zip);
  if (!isAffected && shippedVersion === version &&
      fingerprintsDiffer(shippedZipManifest(agent, shippedVersion), zipManifestText(zip))) {
    version = resolveShipVersion(version, true);
    console.log(`  payload differs from shipped ${shippedVersion} — re-versioning to ${version} (gh-812: never republish changed content under a shipped version)`);
    zip = buildPack(agent, version);
    augmentLaunchSurface(agent, zip);
