{"content":"const { execSync } = require('child_process');
const fs = require('fs'), path = require('path');
const { payloadFingerprint } = require('/tmp/e2e/ci/pack_version_guard.cjs');

const newCatalog = JSON.parse(fs.readFileSync('/tmp/e2e/dist/catalog.json', 'utf8'));
const oldCatalog = JSON.parse(fs.readFileSync('/tmp/incident/075526/catalog.json', 'utf8'));

function manifestOf(zip) {
  return execSync(`unzip -p ${JSON.stringify(zip)} manifest.json`, { encoding: 'utf8' });
}

function semverGt(a, b) {
  const [a1, a2, a3] = a.split('.').map(Number);
  const [b1, b2, b3] = b.split('.').map(Number);
  return a1 > b1 || (a1 === b1 && a2 > b2) || (a1 === b1 && a2 === b2 && a3 > b3);
}

let collisions = 0, bumped = 0, identical = 0, missing = 0;
for (const agent of Object.keys(newCatalog).sort()) {
  const nv = newCatalog[agent], ov = oldCatalog[agent];
  const newZip = `/tmp/e2e/dist/${agent}-${nv}.zip`;
  if (!fs.existsSync(newZip)) { console.log('MISSING NEW ZIP: ' + agent); missing++; continue; }
  if (ov === undefined || semverGt(nv, ov)) { bumped++; continue; }
  // same version as 075526 shipped — the payload MUST be identical (AC2)
  const oldZip = `/tmp/incident/075526/${agent}-${ov}.zip`;
  if (!fs.existsSync(oldZip)) { console.log('no old zip for ' + agent + ' — treated as bumped'); bumped++; continue; }
  if (payloadFingerprint(manifestOf(newZip)) === payloadFingerprint(manifestOf(oldZip))) {
    identical++;
  } else {
    console.log(`COLLISION: ${agent} v${nv} same version as 075526 but DIFFERENT payload`);
    collisions++;
  }
}
console.log(`agents=${Object.keys(newCatalog).length} bumped=${bumped} identicalAtSameVersion=${identical} collisions=${collisions} missingNew=${missing}`);
console.log(fs.existsSync('/tmp/e2e/dist/sm_github-0.1.36.zip') ? 'FAIL: sm_github-0.1.36.zip exists again' : 'OK: no sm_github-0.1.36.zip in the new release');
