const { execSync } = require("child_process");
const fs = require("fs");
const { unresolvedRequires } = require("/tmp/e2e/ci/pack_require_gate.cjs");
const dir = "/tmp/gate-red/inspect";
fs.rmSync(dir, { recursive: true, force: true });
execSync("unzip -q -o /tmp/gate-red/tampered.zip -d " + dir);
const paths = new Set(); const sources = [];
const walk = (d, rel) => { for (const e of fs.readdirSync(d, { withFileTypes: true })) {
  const rp = rel ? rel + "/" + e.name : e.name;
  if (e.isDirectory()) walk(d + "/" + e.name, rp);
  else { paths.add(rp); if (rp.endsWith(".js")) sources.push({ path: rp, source: fs.readFileSync(d + "/" + e.name, "utf8") }); }
} };
walk(dir, "");
const unresolved = unresolvedRequires(sources, paths);
console.log("unresolved count:", unresolved.length);
unresolved.slice(0, 3).forEach(u => console.log(`  ${u.from}: require("${u.spec}") -> none of [${u.bases.join(", ")}] is in the zip`));
process.exit(unresolved.length > 0 ? 1 : 0);
